// Regenerate only the used Material Design SVG paths; no font/network at runtime.
import fs from 'node:fs';
import path from 'node:path';
import * as mdi from '@mdi/js';
const files = [];
function walk(dir) { for (const entry of fs.readdirSync(dir,{withFileTypes:true})) { const p=path.join(dir,entry.name); if(entry.isDirectory())walk(p); else if(/\.(vue|ts)$/.test(p)&&!p.endsWith('iconPaths.ts'))files.push(p); } }
walk('src');
const names=new Set(['mdi-vector-square']);
for(const p of files) { let s=fs.readFileSync(p,'utf8'); for(const m of s.matchAll(/mdi-[a-z0-9-]+/g))names.add(m[0]);
  if(p.endsWith('.vue')) { s=s.replace(/<i\b([^>]*\bclass="mdi\b[^>]*)>\s*<\/i>/g,'<MdiIcon$1 />'); fs.writeFileSync(p,s); }
}
const paths={};
for(const name of [...names].sort()) { const key=name.replace(/-([a-z0-9])/g,(_,c)=>c.toUpperCase()); if(mdi[key])paths[name]=mdi[key]; }
fs.writeFileSync('src/lib/iconPaths.ts', '// Generated by generate-icons.mjs from @mdi/js (Apache-2.0).\nexport const paths: Record<string,string> = '+JSON.stringify(paths,null,2)+'\n');
fs.copyFileSync('node_modules/@mdi/js/LICENSE','MDI-LICENSE');
console.log(`${Object.keys(paths).length} bundled SVG icons`);
